const lancamentos = $('Ler Lançamentos do Mês').all().map(i => i.json);
const orcamentos  = $('Ler Orçamentos').all().map(i => i.json);
const mes         = $('Webhook – Receber Trigger').first().json.body?.mes || '';
const chatId      = String($('Webhook – Receber Trigger').first().json.body?.chatId || '');

// Mapa de limites
const limites = {};
orcamentos.forEach(o => {
  const cat   = o['Categoria'] || '';
  const limite = parseFloat(o['Limite Mensal (R$)'] || 0);
  if (cat && limite > 0) limites[cat] = limite;
});

// Somar despesas por categoria
const gastos = {};
lancamentos.forEach(l => {
  if ((l['Tipo']||'') === 'Despesa') {
    const cat = l['Categoria'] || 'Outros';
    const val = parseFloat(l['Valor (R$)'] || 0);
    gastos[cat] = (gastos[cat] || 0) + val;
  }
});

// Classificar categorias
const alertas_100 = [];
const alertas_80  = [];

Object.entries(gastos).forEach(([cat, gasto]) => {
  const limite = limites[cat];
  if (!limite) return;
  const pct = gasto / limite;
  if (pct >= 1.0) alertas_100.push({ cat, gasto, limite, pct });
  else if (pct >= 0.8) alertas_80.push({ cat, gasto, limite, pct });
});

if (alertas_100.length === 0 && alertas_80.length === 0) {
  return [{ json: { enviar: false, mes, chatId } }];
}

// Montar mensagem
let msg = `⚠️ *Alerta de Orçamento — ${mes}*\n\n`;

if (alertas_100.length > 0) {
  msg += `🔴 *LIMITE ULTRAPASSADO:*\n`;
  alertas_100.forEach(a => {
    const excesso = a.gasto - a.limite;
    msg += `  • *${a.cat}:* R\$ ${a.gasto.toFixed(2).replace('.',',')} de R\$ ${a.limite.toFixed(2).replace('.',',')} \(${(a.pct*100).toFixed(0)}%\) — excedeu R\$ ${excesso.toFixed(2).replace('.',',')}\n`;
  });
  msg += '\n';
}

if (alertas_80.length > 0) {
  msg += `🟡 *ATENÇÃO — próximo do limite:*\n`;
  alertas_80.forEach(a => {
    const restante = a.limite - a.gasto;
    msg += `  • *${a.cat}:* R\$ ${a.gasto.toFixed(2).replace('.',',')} de R\$ ${a.limite.toFixed(2).replace('.',',')} \(${(a.pct*100).toFixed(0)}%\) — sobram R\$ ${restante.toFixed(2).replace('.',',')}\n`;
  });
}

msg += `\n_Acesse o Google Sheets para ver o detalhamento\.`;

return [{ json: { enviar: true, mes, chatId, mensagem: msg, alertas_100, alertas_80 } }];
